def solve():
    count = 0
    # Iterate through all possible values for a, b, c, d from 1 to 5
    for a in range(1, 6):
        for b in range(1, 6):
            for c in range(1, 6):
                for d in range(1, 6):
                    # Calculate the expression modulo 5
                    # a^2 + b^2 + c^3 - d^3 mod 5

                    # We can use the values a, b, c, d directly and take modulo 5 at the end
                    # or calculate the residues first. Using direct calculation is safe.

                    val = a**2 + b**2 + c**3 - d**3

                    if val % 5 == 0:
                        count += 1
                        # Optional: print a few examples to check logic
                        # if count <= 5:
                        #     print(f"Found: ({a}, {b}, {c}, {d})")
    return count

print(solve())

p = 61
N2 = {r: 0 for r in range(p)}

for a in range(p):
    a_sq = (a * a) % p
    for b in range(p):
        b_sq = (b * b) % p
        r = (a_sq + b_sq) % p
        N2[r] += 1

# Print the results neatly
results = {r: N2[r] for r in range(p)}
print(results)

